        if first {
            first = false
            let t = line.trim()
            let mut valid = t.len() > 0
            for c in t.chars() {
                if c < '0' || c > '9' {
                    valid = false
                }
            }
            if valid {
                match t.parse::<int>() {
                    Ok(n) => {
                        if n > 0 {
                            width = n
                            ok = true
                        }
                    }
                    Err(_) => {}
                }
            }
        } else {
            rest = rest + line + " "
        }
    }
    if !ok {
        println("error: bad width")
        process::exit(1)
    }
    let mut cur = ""
