    for w in rest.split_whitespace() {
        let wl: int = w.chars().count() as int
        if curlen == 0 {
            cur = w
            curlen = wl
        } else if curlen + 1 + wl <= width {
            cur = cur + " " + w
            curlen = curlen + 1 + wl
        } else {
            println(cur)
            cur = w
            curlen = wl
        }
    }
    if curlen > 0 {
        println(cur)
    }
